"""Deterministic coverage for the SCORING logic inside tests/e2e/proofread-recall.mjs
-- without calling any model.

Why this file exists: the harness's own comment used to claim "Mechanical: 0/9,
Editorial: 0/5" was a real result, when in fact `callClaudeHeadless` was returning the
`claude -p ... --output-format json` ENVELOPE (top-level fields like type/subtype/
is_error/result/session_id) unparsed, so `extractJson` happily parsed the envelope,
found no `changes` array, and the harness silently reported a clean 0/9 -- indistin-
guishable from "the model genuinely found nothing". That gap (a measurement that
cannot tell "found nothing" from "couldn't read the answer") is what this test file
exists to close, by proving the scorer can tell those cases apart BEFORE trusting any
number it prints against a real model.

Mechanism: the harness supports a test-only escape hatch, the environment variable
PROOFREAD_RECALL_FAKE_RESPONSE, documented in its own header comment. When set to a
file path, every `callClaudeHeadless` call (both the mechanical and the editorial
stage) returns that file's contents instead of invoking the `claude` CLI. This lets us
drive the harness's envelope-unwrapping, JSON-extraction, `changes`-array detection,
and hit/miss counting end-to-end via a real subprocess run, with a synthetic response
we control, no model, no tokens, no dependency on the `claude` CLI being installed.

The critical case is the perfect (9/9) response: if the scorer cannot recognize a
response containing all nine expected `before` strings as a perfect score, no other
number it ever prints is trustworthy.

Owns only tests/e2e/proofread-recall.mjs (read-only) and this test file.
"""

import json
import os
import shutil
import subprocess
import sys
import tempfile
import unittest

ROOT_DIR = os.path.dirname(os.path.abspath(__file__))
REPO_DIR = os.path.dirname(ROOT_DIR)
HARNESS_PATH = os.path.join(REPO_DIR, "tests", "e2e", "proofread-recall.mjs")
EXPECTED_MECHANICAL_PATH = os.path.join(
    ROOT_DIR, "fixtures", "proofread", "hebrew-recall", "expected-mechanical.json"
)


def _find_node():
    return shutil.which("node")


def _load_expected_before_strings():
    with open(EXPECTED_MECHANICAL_PATH, encoding="utf-8") as fh:
        data = json.load(fh)
    return [entry["before"] for entry in data["errors"]]


def _run_harness_with_fake_response(fake_response_text, tmp_dir):
    """Writes fake_response_text to a scratch file, runs the harness with
    PROOFREAD_RECALL_FAKE_RESPONSE pointed at it, and returns (returncode, stdout)."""
    fake_path = os.path.join(tmp_dir, "fake-response.txt")
    with open(fake_path, "w", encoding="utf-8") as fh:
        fh.write(fake_response_text)

    env = dict(os.environ)
    env["PROOFREAD_RECALL_FAKE_RESPONSE"] = fake_path

    node = _find_node()
    result = subprocess.run(
        [node, HARNESS_PATH],
        capture_output=True,
        text=True,
        timeout=60,
        env=env,
        cwd=REPO_DIR,
    )
    return result.returncode, result.stdout, result.stderr


@unittest.skipIf(_find_node() is None, "node not found on PATH")
class TestEvalHarnessScoring(unittest.TestCase):
    """Exercises tests/e2e/proofread-recall.mjs's scoring path via
    PROOFREAD_RECALL_FAKE_RESPONSE, with no model call."""

    def setUp(self):
        self.tmp_dir = tempfile.mkdtemp()
        self.addCleanup(shutil.rmtree, self.tmp_dir, ignore_errors=True)
        self.expected_befores = _load_expected_before_strings()
        self.assertEqual(
            len(self.expected_befores),
            9,
            "expected-mechanical.json no longer has exactly nine errors -- update this test",
        )

    def test_all_nine_before_strings_scores_9_of_9_and_exits_zero(self):
        """The critical case: if the scorer cannot recognize a perfect response as
        perfect, every other number it prints is meaningless."""
        fake = json.dumps(
            {
                "stage": "mechanical",
                "changes": [{"before": b, "after": "x"} for b in self.expected_befores],
            },
            ensure_ascii=False,
        )
        returncode, stdout, stderr = _run_harness_with_fake_response(fake, self.tmp_dir)

        self.assertEqual(
            returncode, 0, f"expected exit 0 for a perfect valid run.\nstdout={stdout}\nstderr={stderr}"
        )
        self.assertIn("Mechanical: 9/9", stdout)
        self.assertNotIn("INVALID RUN", stdout)
        for i in range(1, 10):
            self.assertIn(f"[HIT ] err-0{i}", stdout)

    def test_well_formed_empty_changes_array_scores_0_of_9_and_is_a_real_zero(self):
        fake = json.dumps({"stage": "mechanical", "changes": []}, ensure_ascii=False)
        returncode, stdout, stderr = _run_harness_with_fake_response(fake, self.tmp_dir)

        self.assertEqual(
            returncode, 0, f"expected exit 0 for a well-formed empty (real zero) run.\nstdout={stdout}\nstderr={stderr}"
        )
        self.assertIn("Mechanical: 0/9", stdout)
        self.assertNotIn("INVALID RUN", stdout)
        self.assertIn("real measurement", stdout)

    def test_unparseable_response_is_reported_invalid_and_exits_nonzero(self):
        fake = "I refuse to answer this request for reasons unrelated to JSON."
        returncode, stdout, stderr = _run_harness_with_fake_response(fake, self.tmp_dir)

        self.assertNotEqual(
            returncode, 0, f"expected a non-zero exit for an invalid (unparseable) run.\nstdout={stdout}\nstderr={stderr}"
        )
        self.assertIn("INVALID RUN", stdout)
        self.assertIn("Mechanical", stdout)
        # An invalid run must not silently masquerade as a real, recordable zero.
        self.assertIn("NOT a measurement", stdout)

    def test_exactly_four_of_nine_scores_4_of_9(self):
        four = self.expected_befores[:4]
        fake = json.dumps(
            {"stage": "mechanical", "changes": [{"before": b, "after": "x"} for b in four]},
            ensure_ascii=False,
        )
        returncode, stdout, stderr = _run_harness_with_fake_response(fake, self.tmp_dir)

        self.assertEqual(
            returncode, 0, f"expected exit 0 for a valid partial-recall run.\nstdout={stdout}\nstderr={stderr}"
        )
        self.assertIn("Mechanical: 4/9", stdout)
        self.assertNotIn("INVALID RUN", stdout)
        for i in range(1, 5):
            self.assertIn(f"[HIT ] err-0{i}", stdout)
        for i in range(5, 10):
            self.assertIn(f"[MISS] err-0{i}", stdout)


if __name__ == "__main__":
    unittest.main()
